interactions.prompt:
You MUST make sure that the agent events are exactly like this. There are shared information (agent level, message level).

Events
```yaml
git:
  commit:
    starting: # pre-commit
      message: {{COMMITMESSAGE}} 
    ended: # post-commit
      sha: {{COMMITSHA}}
      message: {{COMMITMESSAGE}}
agent:
  started:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
    llm: {{LLM}}
    transcript: {{TRANSSCRIPTPATH}}
    parent: {{PARENT}}
  ended:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
    llm: {{LLM}}
    transcript: {{TRANSSCRIPTPATH}}
    message: {{MESSAGEID}}
    parent: {{PARENTMESSAGEID}}
  prompt:
    submitting:
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      llm: {{LLM}}
      message: {{MESSAGEID}}
      parent: {{PARENTMESSAGEID}}
      prompt: {{PROMPT}}
  compacting:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
    llm: {{LLM}}
    transcript: {{TRANSSCRIPTPATH}}
    message: {{MESSAGEID}}
    parent: {{PARENTMESSAGEID}}
    chat: {{CHAT}}
  tool:
    starting: # all tools but excluding task, code, terminal
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      llm: {{LLM}}
      transcript: {{TRANSSCRIPTPATH}}
      message: {{MESSAGEID}}
      parent: {{PARENTMESSAGEID}}
      name: {{NAME}} # name of the tool
      input: {{INPUT}}
    ended: # excluding task, code and terminal
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      llm: {{LLM}}
      transcript: {{TRANSSCRIPTPATH}}
      message: {{MESSAGEID}}
      parent: {{PARENTMESSAGEID}}
      name: {{NAME}} # name of the tool
      input: {{INPUT}}
      response: {{RESPONSE}}
    plan: # A list of tasks - usually TODO lists in the native clients
      updating: # Planning involves changing the task list
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        llm: {{LLM}}
        transcript: {{TRANSSCRIPTPATH}}
        message: {{MESSAGEID}}
        parent: {{PARENTMESSAGEID}}
        steps:
          - name: {{STEPNAME}}
          - status: {{STATUS}} # completed, in progress, pending
    searching: # All searches such as file read, grep, websearch
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      llm: {{LLM}}
      transcript: {{TRANSSCRIPTPATH}}
      message: {{MESSAGEID}}
      parent: {{PARENTMESSAGEID}}
      query: {{QUERY}} # regex, glob, file path, url, etc
      include: [{{INCLUDEPATTERN}}] # file glob patterns, line numbers, etc
      exclude: [{{EXCLUDEPATTERN}}]
    code:
      editing:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        llm: {{LLM}}
        transcript: {{TRANSSCRIPTPATH}}
        message: {{MESSAGEID}}
        parent: {{PARENTMESSAGEID}}
        path: {{FILEPATH}}
        old: {{OLDSTRING}}
        new: {{NEWSTRING}}
        all: {{REPLACEALLSTRINGS}} # false: just first, true: replace all occurrences
      edited:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        llm: {{LLM}}
        transcript: {{TRANSSCRIPTPATH}}
        message: {{MESSAGEID}}
        parent: {{PARENTMESSAGEID}}
        path: {{FILEPATH}}
        old: {{OLDSTRING}}
        new: {{NEWSTRING}}
    terminal:
      starting:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        llm: {{LLM}}
        transcript: {{TRANSSCRIPTPATH}}
        message: {{MESSAGEID}}
        parent: {{PARENTMESSAGEID}}
        command: {{COMMAND}}
      ended:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        llm: {{LLM}}
        transcript: {{TRANSSCRIPTPATH}}
        message: {{MESSAGEID}}
        parent: {{PARENTMESSAGEID}}
        command: {{COMMAND}}
        pid: {{PID}} # process id, execution id, etc
        terminated: {{HASTERMINATED}} # true: stopped, false: still running
        stdout: {{STDOUT}}
        stderr: {{STDERR}}
```
